{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 빌린 공공자전거 도난 시 새 자전거 값 전부 배상 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "조례 제12조의2 제6항에 따르면, 시장은 공공자전거 이용자가 고의 또는 과실 등의 귀책사유로 도난·분실·파손 등의 손실을 초래한 경우 이용자에게 원상복구 또는 손해배상을 요구할 수 있습니다. 다만 이 조항은 손해의 범위나 배상액이 새 자전거 값 전부인지 여부를 직접 정하지 않고, 배상 요구의 근거와 방식(원상복구 또는 손해배상)만 정하고 있습니다. 따라서 새 자전거 값 전부를 배상해야 하는지는 이 조문만으로 단정할 수 없습니다.",
          "b_ids": "자전거:제12조의2제6항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
